}


// Only for candidates whose full name is unique in both complete inventories.
// Never use this to discover candidates, authorize deletion, or match by name alone.

function richIdentity({contactData:d,existingVcard,uid}){
 if(!d?.name)return null;
 const names=patchSharedFields({uid,existingVcard,contactData:{name:d.name}});
 if(names.changed)return null;
 const projected=patchSharedFields({uid,existingVcard,contactData:d,projectionOnly:true});
 const exact=field=>Object.hasOwn(projected,field)&&!patchSharedFields({uid,existingVcard,contactData:{[field]:projected[field]}}).changed;
 if(d.phoneNumbers?.some(x=>typeof x.value==='string'&&/^[+0-9 ().-]+$/.test(x.value)&&/^\d{10,15}$/.test(x.value.replace(/\D/g,'')))&&exact('phoneNumbers'))return 'unique_name_and_exact_phone_group';
 if(d.addresses?.some(x=>x.street?.trim()&&(x.postalCode?.trim()||x.city?.trim()))&&exact('addresses'))return 'unique_name_and_complete_address';
 if(Number.isInteger(d.birthday?.year)&&exact('birthday'))return 'unique_name_and_full_birthday';
 const social=new Set(['linkedin','twitter','github','keybase','facebook','instagram']);
 if(d.urls?.some(x=>social.has(String(x.type).toLowerCase())&&/^https?:\/\/[^/\s]+\/[^\s]+$/i.test(x.value||''))&&exact('urls'))return 'unique_name_and_profile_url';
 if(d.organizations?.[0]?.name?.trim()&&d.organizations[0].title?.trim()&&exact('organizations'))return 'unique_name_and_company_title';
 if(typeof d.notes==='string'&&d.notes.trim().length>=40&&exact('notes'))return 'unique_name_and_exact_notes';
 return null;
}


// Read-only review of previously unique candidates. Never discovers uniqueness,
// changes contacts, or accepts missing/multiple resource responses.




function reviewMatchBatch({candidates,sourceResponse,targetResponse,bookPath,acceptInitialDifferences=false,acceptCorroboratedNames=false,allowUniqueNameCorroboration=false}){
 const parse=x=>typeof x==='string'?JSON.parse(x):x,arr=x=>x==null?[]:Array.isArray(x)?x:[x];
 const scalar=x=>{x=arr(x)[0];return x&&typeof x==='object'?x._value:x;};
 const s=parse(sourceResponse),t=parse(targetResponse);candidates=parse(candidates);
 if(!Array.isArray(candidates)||!candidates.length||candidates.length>100)throw Error('Bounded candidate batch required');
 if(!/^\/[A-Za-z0-9/_-]+\/$/.test(bookPath))throw Error('Fixed book path required');
 const sourceIds=candidates.map(x=>x.sourceId),targetIds=candidates.map(x=>x.targetId);
 if(sourceIds.some(x=>!x)||targetIds.some(x=>!/^[A-Za-z0-9_-]{1,128}$/.test(x))||new Set(sourceIds).size!==candidates.length||new Set(targetIds).size!==candidates.length)throw Error('Candidates must be one-to-one');
 if(s.statusCode!==200||t.statusCode!==207)throw Error('Both batch reads must succeed');
 const sourceBody=parse(s.body),targetBody=parse(t.body);
 if(!Array.isArray(sourceBody?.contacts)||!targetBody?.multistatus)throw Error('Incomplete batch envelope');
 const sources=new Map(),targets=new Map();
 for(const row of sourceBody.contacts){if(!sourceIds.includes(row.contactId)||sources.has(row.contactId))throw Error('Unexpected or duplicate source');sources.set(row.contactId,row);}
 for(const row of arr(targetBody.multistatus.response)){
  const href=scalar(row.href),targetId=targetIds.find(uid=>[uid,Buffer.from(uid).toString('base64')].some(leaf=>href===bookPath+leaf+'.vcf'));
  if(!targetId||targets.has(targetId))throw Error('Unexpected or duplicate target resource');
  const ps=arr(row.propstat).find(p=>/^HTTP\/1\.[01] 200(?: |$)/.test(scalar(p.status)||''));
  const prop=arr(ps?.prop)[0];targets.set(targetId,{resourceName:href.slice(bookPath.length),card:scalar(prop?.['address-data']),etag:scalar(prop?.getetag)});
 }
 return candidates.map(({sourceId,targetId:uid})=>{
  const hold=reason=>({status:'held',sourceId,uid,reason});
  const source=sources.get(sourceId),target=targets.get(uid);
  if(!source||!target?.card)return hold('missing_resource');
  try{
   if(typeof source.etag!=='string'||!source.etag||!/^"[^"\r\n]+"$/.test(target.etag||''))throw Error('Missing version evidence');
   const evidence=bootstrapEvidence({contactData:source.contactData,existingVcard:target.card})||(allowUniqueNameCorroboration?richIdentity({contactData:source.contactData,existingVcard:target.card,uid}):null);
   if(!evidence)return hold('no_strong_identifier');
   const diff=patchSharedFields({uid,existingVcard:target.card,contactData:source.contactData});
   // Enrollment records both current versions without modifying either. Future
   // source edits still require an unchanged target field. Never use this option
   // to relax identity: differing structured names remain held.
   if(diff.changed&&(!acceptInitialDifferences||(diff.changedFields.includes('name')&&!(acceptCorroboratedNames&&['exact_email_and_phone','exact_email_and_compatible_name','exact_email_and_structured_name'].includes(evidence)))))return {...hold('shared_field_differences'),fields:diff.changedFields};
   return {status:'eligible',sourceId,uid,resourceName:target.resourceName,sourceEtag:source.etag,targetEtag:target.etag,baselineJson:JSON.stringify(snapshot({sourceContactId:sourceId,uid,existingVcard:target.card,contactData:source.contactData}))};
  }catch(e){return hold(String(e.message));}
 });
}


return {rows:reviewMatchBatch({...input,bookPath:'/book/'})};
